/**
 * Initializes the menu.
 *
 * Initialize will call BaseMenu's initialize method
 * as well as set up focus,
 * click,
 * hover,
 * keydown,
 * keyup, and
 * focusout events for the menu.
 *
 * If the BaseMenu's initialize method throws an error,
 * this will catch it and log it to the console.
 */
initialize() {
  try {
    super.initialize();

    this._handleFocus();
    this._handleClick();
    this._handleHover();
    this._handleKeydown();
    this._handleKeyup();
    this._handleFocusBlur();
  } catch (error) {
    console.error(error);
  }
}

/**
 * Handles focusout events to close the menu when focus leaves.
 *
 * @protected
 */
_handleFocusBlur() {
  this.dom.menu.addEventListener("focusout", (event) => {
    if (!this.dom.menu.contains(event.relatedTarget)) {
      this.blur();
      this.closeChildren();
      if (this.elements.controller) {
        this.elements.controller.close();
      }
    }
  });
}

/**
